INSERT INTO public.knowledge_base (content, metadata, embedding, user_id) VALUES ('swoim majątkiem solidarnie z pozostałymi wspólnikami oraz ze spółką, 
z uwzględnieniem art. 31. 
Art. 23. Umowa spółki powinna być zawarta na piśmie pod rygorem 
